program_text='''def transform(grid):
    out = [row[:] for row in grid]
    height, width = len(grid), len(grid[0])

    # Horizontal bars are the dense rows; isolated pixels below them are
    # the vertical stems to connect.
    horizontal_rows = [r for r, row in enumerate(grid) if sum(v != 0 for v in row) >= 3]
    if not horizontal_rows:
        return out
    last_horizontal = horizontal_rows[-1]
    stems = {}
    for c in range(width):
        below = [grid[r][c] for r in range(last_horizontal + 1, height) if grid[r][c] != 0]
        if below:
            stems[c] = below[0]

    for c, stem_color in stems.items():
        crossings = []
        for r in horizontal_rows:
            left = next((grid[r][x] for x in range(c - 1, -1, -1) if grid[r][x] != 0), 0)
            right = next((grid[r][x] for x in range(c + 1, width) if grid[r][x] != 0), 0)
            if left and left == right:
                out[r][c] = left
                crossings.append((r, left))

        # Each horizontal crossing colors the vertical stem upward to the
        # next crossing; the bottom section keeps the stem's own color.
        for i, (r, color) in enumerate(crossings):
            start = 0 if i == 0 else crossings[i - 1][0] + 1
            for y in range(start, r + 1):
                out[y][c] = color
        if crossings:
            for y in range(crossings[-1][0] + 1, height):
                out[y][c] = stem_color
        else:
            for y in range(last_horizontal + 1, height):
                out[y][c] = stem_color
    return out
'''
